<template>
    <div class="col-11 row mx-auto my-2 strikeList"  style="height:110px">
        <!--<div class="col-15"></div>-->
        <strikes
            v-for="strike in ibsStrikes" 
            
            :key="strike.name" 
            :is="strike.obj"
            
            :json="ibsStrikes"
            :strike="strike"
        />
        <frac></frac>
        <!--<div class="col-15"></div>-->
    </div>
    <div class="col-11 row mx-auto my-2 strikeList">
        <!--<div class="col-075"></div>-->
        <strikes
            v-for="strike in eodStrikes" 
            
            :key="strike.name" 
            :is="strike.obj"
            
            :json="eodStrikes"
            :strike="strike"
        />
        <div class="col-15 px-1">
            <div class="strikeSoto roundedz bg-darkz text-white px-0 border border-warning">
	    	<a :href="sotoStrikes[0].wiki" target="_blank">
	    		<h5 class="text-center pt-3 pb-3 roundedz-top">SOTO</h5>
	    	</a>
            <div class="row m-0 p-0">
	    	    <div :ref="sotoStrikes[0].class" :id="sotoStrikes[0].class" class="col-4 mb-2 mx-auto roundedz px-0 d-inline-block soto1">
			    	<a :href="sotoStrikes[0].video" target="_blank" style="text-decoration: none;color:inherit;">
			    		<p class="w-100 my-1 text-center px-0">{{sotoStrikes[0].name}}</p>
			    	</a>
			    </div>

                <div :ref="sotoStrikes[1].class" :id="sotoStrikes[1].class" class="col-4 mb-2 mx-auto roundedz px-0 d-inline-block soto2">
			    	<a :href="sotoStrikes[1].video" target="_blank" style="text-decoration: none;color:inherit;">
			    		<p class="w-100 my-1 text-center px-0">{{sotoStrikes[1].name}}</p>
			    	</a>
			    </div>
            </div>
	    	<div class="row pt-2"><img class="d-none" src="#"></div>
	    </div>
        </div>
    </div>
    <a target="_blank" href="https://www.paypal.com/donate/?hosted_button_id=7J3VDAT6LVY7C"><img class="donateImgz mt-2 col-6 mx-auto" src="../img/donate_gem.png"></a>
</template>

<script>
    import strikes from '../components/strikes_component.vue'
    import json from '../assets/gw2_progression_data.json'
    import frac from '../views/fractal_view.vue'

    export default 
      {
        name: 'strikes_view',
        data(){
            return{
                eodStrikes: json.strikes,
                ibsStrikes: json.ibs,
                sotoStrikes: json.soto,
                
                dailyIBS: "",
                dailyEOD: "",
            }
        },
        components: { 
            strikes,
            frac
        },
        methods: {
            dailyEODPick(id){
                switch(id){
                    case 6353: // AH
                        document.querySelector(".s1").style.border = "1px solid yellow";
                        break;
                    case 6307: // HT
                        document.querySelector(".s4").style.border = "1px solid yellow";
                        break;
                    case 6327: // KO
                        document.querySelector(".s3").style.border = "1px solid yellow";
                        break;
                    case 6457: // XJ
                        document.querySelector(".s2").style.border = "1px solid yellow";
                        break;
                    case 6803: // OLC
                        document.querySelector(".s5").style.border = "1px solid yellow";
                        break;
                }   
            },
            dailyIBSPick(id){
                switch(id){
                    case 5328: // cold war
                        document.querySelector(".ibs1").style.border = "1px solid yellow";
                        break;
                    case 5233: // freanir of jormag
                        document.querySelector(".ibs2").style.border = "1px solid yellow";
                        break; 
                    case 5239: // shiverpeaks pass
                        document.querySelector(".ibs3").style.border = "1px solid yellow";
                        break;
                    case 5207: // voice of the fallen and claw of the fallen
                        document.querySelector(".ibs4").style.border = "1px solid yellow";
                        break;
                    case 5210: // whisper of jormag
                        document.querySelector(".ibs5").style.border = "1px solid yellow";
                        break; 
                    case 5194: // boneskinner
                        document.querySelector(".ibs6").style.border = "1px solid yellow";
                        break;
                }
            },
            dailySOTOPick(id){
                switch(id){
                    case 7130: // Cosmic Observatory
                        document.querySelector(".soto1").style.border = "1px solid yellow";
                        document.querySelector(".soto2").style.border = "1px solid #0d6efd";
                        break;
                    case 7154: // Temple of Febe
                        document.querySelector(".soto1").style.border = "1px solid #0d6efd";
                        document.querySelector(".soto2").style.border = "1px solid yellow";
                        break;
                }
            },
            getStrikes: function(){
                fetch(`https://api.guildwars2.com/v2/achievements/categories/250`)
			        .then(r => r.json())
			        .then(data => { 
                        this.dailyIBS = data.achievements[0]; 
                        this.dailyEOD = data.achievements[1];
                        this.dailySoto = data.achievements[2];
                        
                        console.log("IBS: " + this.dailyIBS);
                        console.log("EOD: " + this.dailyEOD);
                        console.log("EOD: " + this.dailySoto);

                        this.dailyIBSPick(this.dailyIBS);
                        this.dailyEODPick(this.dailyEOD);
                        this.dailySOTOPick(this.dailySoto);
                    });
            }          
        },
        mounted(){
            this.getStrikes();
        }
    }
</script>

<style scoped>


  .strikeSoto a h5{
    color: #FFFFFF;
	/*text-shadow: 1px 1px #007bff,-1px -1px #007bff;*/
	text-shadow: 1px 1px #343a40,-1px -1px #343a40;
	font-size: 15px;
	background-size: cover;
	background-repeat: no-repeat;
	font-family: 'Work Sans', sans-serif;
	font-weight: bold;
	letter-spacing: 1.5px;
	text-align: center;
  }

  .strikeSoto h5{
	background: url(../img/strikes/co.png);
  }


@media (max-width: 1899px){
    .donateImgz{
        position: fixed;
        bottom: 20px;
        right: 10px;
        max-width: 50px;
        max-height: 50px;
    }
}

@media (max-width: 1300px){
    .donateImgz{
        position: fixed;
        bottom: 15px;
        right: 10px;
        max-width: 35px;
        max-height: 35px;
    }
}

@media (min-width: 1900px){
    .donateImgz{
        position: fixed;
        bottom: 20px;
        right: 10px;
        max-width: 70px;
        max-height: 70px;
    }
}


.donateImgz:hover{
    transform: scale(1.2);
}

</style>

